gusta la zanahoria.","Me gusta la cesta.","Me gusta el granjero."]},{"type":"Traduce la frase","en":"I like the basket.","es":"Me gusta la cesta.","opts":["Me gusta la cesta.","Me gusta el granjero.","Me gusta la tienda de la granja."]},{"type":"Traduce la frase","en":"I like the farmer.","es":"Me gusta el granjero.","opts":["Me gusta el granjero.","Me gusta la tienda de la granja.","Me gusta el huevo."]},{"type":"Traduce la frase","en":"This is the farm shop.","es":"Esto es la tienda de la granja.","opts":["Esto es la tienda de la granja.","Esto es el huevo.","Esto es la leche."]},{"type":"Traduce la frase","en":"This is the egg.","es":"Esto es el huevo.","opts":["Esto es el huevo.","Esto es la leche.","Esto es el queso."]},{"type":"Traduce la frase","en":"This is the milk.","es":"Esto es la leche.","opts":["Esto es la leche.","Esto es el queso.","Esto es la miel."]},{"type":"Traduce la frase","en":"This is the cheese.","es":"Esto es el queso.","opts":["Esto es el queso.","Esto es la miel.","Esto es la manzana."]},{"type":"Traduce la frase","en":"This is the honey.","es":"Esto es la miel.","opts":["Esto es la miel.","Esto es la manzana.","Esto es la patata."]},{"type":"Traduce la frase","en":"This is the apple.","es":"Esto es la manzana.","opts":["Esto es la manzana.","Esto es la patata.","Esto es la zanahoria."]},{"type":"Traduce la frase","en":"This is the potato.","es":"Esto es la patata.","opts":["Esto es la patata.","Esto es la zanahoria.","Esto es la cesta."]},{"type":"Traduce la frase","en":"This is the carrot.","es":"Esto es la zanahoria.","opts":["Esto es la zanahoria.","Esto es la cesta.","Esto es el granjero."]},{"type":"Traduce la frase","en":"This is the basket.","es":"Esto es la cesta.","opts":["Esto es la cesta.","Esto es el granjero.","Esto es la tienda de la granja."]},{"type":"Traduce la frase","en":"This is the farmer.","es":"Esto es el granjero.","opts":["Esto es el granjero.","Esto es la tienda de la granja.","Esto es el huevo."]}]};let index=0,score=0,answered=false,matched=new Set();const $=id=>document.getElementById(id);
function say(t){if(!("speechSynthesis" in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang="en-GB";speechSynthesis.speak(u)}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
let selectedWord=null;
function renderWords(){
 const spanish=shuffle(data.words.map((w,i)=>({text:w[1],index:i})));
 $("words").innerHTML='<div class="match-board"><div class="match-column"><p class="match-label">English</p>'+data.words.map((w,i)=>'<div class="match-row"><button class="match-choice" data-en="'+i+'">'+w[0]+'</button><button class="audio" data-audio="'+i+'" aria-label="Escuchar '+w[0]+'">🔊</button></div>').join("")+'</div><div class="match-column"><p class="match-label">Español</p>'+spanish.map(w=>'<button class="match-choice spanish" data-es="'+w.index+'">'+w.text+'</button>').join("")+'</div></div>';
 $("words").querySelectorAll("[data-en]").forEach(b=>b.onclick=()=>{if(matched.has(+b.dataset.en))return;selectedWord=+b.dataset.en;$("words").querySelectorAll("[data-en]").forEach(x=>x.classList.toggle("selected",+x.dataset.en===selectedWord));$("matchresult").textContent="Ahora elige la traducción en español de “"+data.words[selectedWord][0]+"”";});
 $("words").querySelectorAll("[data-es]").forEach(b=>b.onclick=()=>{if(selectedWord===null){$("matchresult").textContent="Primero selecciona una palabra en inglés.";return;}const i=selectedWord;if(+b.dataset.es===i){matched.add(i);$("words").querySelector('[data-en="'+i+'"]').classList.add("matched");$("words").querySelector('[data-en="'+i+'"]').disabled=true;b.classList.add("matched");b.disabled=true;$("matchresult").textContent=matched.size===10?"🎉 ¡Perfecto! Has relacionado las 10 parejas.":"✓ ¡Muy bien! "+matched.size+" de 10 parejas encontradas.";selectedWord=null;}else{$("matchresult").textContent="Casi. Prueba otra traducción para “"+data.words[i][0]+"”.";} $("words").querySelectorAll("[data-en]").forEach(x=>x.classList.toggle("selected",selectedWord!==null&&+x.dataset.en===selectedWord));});
 $("words").querySelectorAll("[data-audio]").forEach(b=>b.onclick=()=>say(data.words[+b.dataset.audio][0]));
}
function render(){const q=data.qs[index];answered=false;$("kind").textContent=q.type;$("counter").textContent="Reto "+(index+1)+" de 50 · Puntuación "+score;$("question").textContent="Traduce al español: “"+q.en+"”";$("bar").style.width=(index/50*100)+"%";$("translation").hidden=true;$("translation").textContent="“"+q.en+"” = "+q.es;$("feedback").textContent="";$("next").hidden=true;$("answers").innerHTML=shuffle(q.opts).map(o=>'<button>'+o+'</button>').join("");$("answers").querySelectorAll("button").forEach(b=>b.onclick=()=>{if(answered)return;answered=true;const ok=b.textContent===q.es;if(ok)score++;$("feedback").textContent=ok?"✓ ¡Correcto!":"La traducción correcta es: "+q.es;$("feedback").style.color=ok?"#21845b":"#a34b42";$("answers").querySelectorAll("button").forEach(x=>{x.disabled=true;if(x.textContent===q.es)x.style.border="2px solid #21845b"});$("next").hidden=false;$("counter").textContent="Reto "+(index+1)+" de 50 · Puntuación "+score})}
$("speak").onclick=()=>say(data.qs[index].en);$("translate").onclick=()=>{$("translation").hidden=!$("translation").hidden;$("translate").textContent=$("translation").hidden?"Ver traducción":"Ocultar traducción"};$("next").onclick=()=>{if(index<49){index++;render()}else{$("question").textContent="¡Has completado los 50 retos!";$("answers").innerHTML="";$("next").hidden=true;$("feedback").textContent="Tu puntuación final: "+score+" de 50";$("bar").style.width="100%"}};

var writingTab=document.createElement("button");writingTab.type="button";writingTab.dataset.tab="writing";writingTab.textContent="3. Writing";document.querySelector("nav").appendChild(writingTab);
var writingPanel=document.createElement("section");writingPanel.id="writing";writingPanel.className="panel";writingPanel.innerHTML='<h2>Writing · Expresión escrita</h2><p class="muted">Practica la escritura en inglés paso a paso con el vocabulario de esta misión. Escribe, revisa y mejora tus respuestas.</p><div id="writing-content"></div>';document.querySelector("main").appendChild(writingPanel);
function renderWriting(){
 var host=document.getElementById("writing-content"),words=(data.words||[]).map(function(w){return {en:String(w[0]||""),es:String(w[1]||"")};}).filter(function(w){return w.en;}),bank=words.map(function(w){return w.en;});
 var stages=[{title:"1. Palabras clave",task:"Escribe cinco palabras de esta misión en inglés y añade su significado en español.",placeholder:"Example: hello = hola…",min:5,needed:2},{title:"2. Mis frases",task:"Escribe dos frases cortas en inglés sobre el tema. Intenta usar al menos dos palabras del banco.",placeholder:"Write your first sentence…",min:6,needed:2},{title:"3. Mi pequeño texto",task:"Escribe un texto de tres o cuatro frases sobre el tema. Usa al menos tres palabras nuevas.",placeholder:"Write your short text here…",min:18,needed:3}];
 host.innerHTML='<div class="translate"><strong>Banco de palabras</strong><p>'+words.map(function(w){return w.en+" = "+w.es;}).join(" · ")+'</p></div>'+stages.map(function(x,i){return '<article class="writing-card"><p class="tag">'+x.title+'</p><p class="muted">'+x.task+'</p><textarea id="writing-input-'+i+'" rows="'+(i===2?6:3)+'" placeholder="'+x.placeholder+'"></textarea><div class="writing-tools"><span id="writing-count-'+i+'" class="muted">0 palabras</span><button type="button" data-writing-review="'+i+'">Revisar mi texto</button></div><p id="writing-feedback-'+i+'" class="writing-feedback" aria-live="polite"></p></article>';}).join("")+'<p class="muted">La revisión es una guía de autoevaluación; el sistema no corrige ni califica automáticamente la gramática de tu texto.</p>';
 var style=document.createElement("style");style.textContent=".writing-card{margin:18px 0;padding:18px;border:1px solid #dce6f7;border-radius:17px;background:linear-gradient(145deg,#f7f9ff,#fff)}.writing-card textarea{display:block;width:100%;box-sizing:border-box;min-height:90px;resize:vertical;border:1px solid #cbd7ee;border-radius:12px;padding:13px;font:inherit;line-height:1.6;color:#20345d;background:#fff}.writing-tools{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin-top:10px}.writing-feedback{min-height:24px;font-weight:750;color:#276b57}.writing-card .tag{margin:0 0 8px}";document.head.appendChild(style);
 stages.forEach(function(x,i){var input=document.getElementById("writing-input-"+i),count=document.getElementById("writing-count-"+i),fb=document.getElementById("writing-feedback-"+i);input.addEventListener("input",function(){var n=input.value.trim()?input.value.trim().split(/\s+/).length:0;count.textContent=n+" palabras";});document.querySelector('[data-writing-review="'+i+'"]').addEventListener("click",function(){var value=input.value.trim();if(!value){fb.textContent="Escribe primero tu respuesta y vuelve a revisarla.";return;}var n=value.split(/\s+/).length,lower=value.toLowerCase(),used=bank.filter(function(w){return lower.includes(w.toLowerCase());}),tips=[];if(!/^[A-Z]/.test(value))tips.push("Empieza con mayúscula.");if(!/[.!?]$/.test(value))tips.push("Añade un punto al final.");if(n<x.min)tips.push("Amplía tu respuesta: intenta escribir un poco más.");if(used.length<x.needed)tips.push("Incorpora más palabras del banco de vocabulario.");fb.textContent=tips.length?"Para mejorar: "+tips.join(" "):"¡Buen trabajo! Has revisado el vocabulario y la presentación. Lee tu texto en voz alta.";});});
}

(function(){var nav=document.querySelector("nav"),main=document.querySelector("main");if(!nav||!main||typeof data==="undefined")return;[["grammar","3. Grammar","Gramática"],["reading","4. Reading","Reading · Comprensión lectora"],["listening","5. Listening","Listening · Comprensión auditiva"]].forEach(function(d){var b=document.createElement("button");b.type="button";b.dataset.tab=d[0];b.textContent=d[1];nav.appendChild(b);var p=document.createElement("section");p.id=d[0];p.className="panel";p.innerHTML="<h2>"+d[2]+"</h2><div id='"+d[0]+"-content'></div>";main.appendChild(p);});var words=data.words.map(function(w){return String(w[0]);}),sentences=data.qs.filter(function(q){return q.type!=="Traduce la palabra"&&q.en&&/[.!?]/.test(q.en);}),unique=[];sentences.forEach(function(q){if(!unique.includes(q.en)&&unique.length<10)unique.push(q.en);});var rules=[[/^I can see the /i,"I can see the…","Usamos «I can see the + nombre» para decir «Puedo ver el/la…»."],[/^Where is the /i,"Where is the…?","Usamos «Where is the…?» para preguntar dónde está algo."],[/^I like the /i,"I like the…","Usamos «I like the + nombre» para expresar gustos."],[/^This is the /i,"This is the…","Usamos «This is the…» para identificar algo."],[/^I have /i,"I have…","Usamos «I have…» para decir lo que tenemos."],[/^It is /i,"It is…","Usamos «It is…» para describir algo."]].filter(function(p){return sentences.some(function(q){return p[0].test(q.en);});});document.getElementById("grammar-content").innerHTML=rules.map(function(p){var q=sentences.find(function(x){return p[0].test(x.en);});return "<article class='skill-card'><b>"+p[1]+"</b><p>"+p[2]+"</p><p class='skill-example'>"+(q?q.en:"")+"</p></article>";}).join("")+"<article class='skill-card'><h3>Practica la estructura</h3><p id='gq' class='question'></p><div id='go' class='answers'></div><p id='gf' class='feedback'></p><button id='gn' hidden>Siguiente</button></article>";var gi=0,gs=sentences.slice(0,8);function gr(){var q=gs[gi];if(!q){document.getElementById("gq").textContent="¡Has terminado!";document.getElementById("go").innerHTML="";return;}document.getElementById("gq").textContent=q.en;document.getElementById("gf").textContent="Elige la traducción correcta.";document.getElementById("gn").hidden=true;document.getElementById("go").innerHTML=q.opts.map(function(x){return "<button type='button'>"+x+"</button>";}).join("");document.querySelectorAll("#go button").forEach(function(b){b.onclick=function(){document.querySelectorAll("#go button").forEach(function(x){x.disabled=true;});document.getElementById("gf").textContent=b.textContent===q.es?"✓ Correcto.":"La respuesta correcta es: "+q.es;document.getElementById("gn").hidden=false;};});}document.getElementById("gn").onclick=function(){gi++;gr();};gr();var passage=unique.slice(0,6);if(!passage.length)passage=words.slice(0,6).map(function(w){return "This is the "+w+".";});document.getElementById("reading-content").innerHTML="<p class='muted'>Lee estas frases en inglés y después comprueba tu comprensión.</p><div class='skill-passage'>"+passage.join(" ")+"</div><article class='skill-card'><h3>Comprensión lectora</h3><p id='rq' class='question'></p><div id='ro' class='answers'></div><p id='rf' class='feedback'></p><button id='rn' hidden>Siguiente</button></article>";var ri=0;function rd(){var target=words[ri%words.length],opts=[target].concat(words.filter(function(w){return w!==target;}).slice(ri%Math.max(1,words.length-1),ri%Math.max(1,words.length-1)+2));document.getElementById("rq").textContent="Which word from the mission vocabulary can you identify in the text?";document.getElementById("rf").textContent="Selecciona una palabra del vocabulario.";document.getElementById("rn").hidden=true;document.getElementById("ro").innerHTML=opts.map(function(x){return "<button type='button'>"+x+"</button>";}).join("");document.querySelectorAll("#ro button").forEach(function(b){b.onclick=function(){document.querySelectorAll("#ro button").forEach(function(x){x.disabled=true;});document.getElementById("rf").textContent=b.textContent===target?"✓ ¡Muy bien!":"Vuelve a leer y busca: "+target;document.getElementById("rn").hidden=false;};});}document.getElementById("rn").onclick=function(){ri++;if(ri>=Math.min(6,words.length)){document.getElementById("rq").textContent="¡Has completado la lectura!";document.getElementById("ro").innerHTML="";document.getElementById("rn").hidden=true;}else rd();};rd();var ls=sentences.slice(-8);if(!ls.length)ls=words.map(function(w){return {en:w};});document.getElementById("listening-content").innerHTML="<p class='muted'>Escucha las frases en inglés británico. Puedes repetir el audio y mostrar la transcripción.</p><article class='skill-card'><button type='button' class='primary' id='lp'>🔊 Escuchar audio</button> <button type='button' id='showt'>Mostrar transcripción</button><p id='lt' class='skill-passage' hidden></p><p id='lq' class='question'>¿Qué palabra escuchas?</p><div id='lo' class='answers'></div><p id='lf' class='feedback'></p><button id='ln' hidden>Siguiente audio</button></article>";var li=0;function lr(){var q=ls[li],target=words.find(function(w){return q.en.toLowerCase().includes(w.toLowerCase());})||words[li%words.length],opts=[target].concat(words.filter(function(w){return w!==target;}).slice(li%Math.max(1,words.length-1),li%Math.max(1,words.length-1)+2));document.getElementById("lt").textContent=q.en;document.getElementById("lt").hidden=true;document.getElementById("lf").textContent="Pulsa «Escuchar audio» y selecciona la palabra que oigas.";document.getElementById("ln").hidden=true;document.getElementById("lo").innerHTML=opts.map(function(x){return "<button type='button'>"+x+"</button>";}).join("");document.getElementById("lp").onclick=function(){if(!window.speechSynthesis)return;speechSynthesis.cancel();var u=new SpeechSynthesisUtterance(q.en);u.lang="en-GB";speechSynthesis.speak(u);};document.querySelectorAll("#lo button").forEach(function(b){b.onclick=function(){document.querySelectorAll("#lo button").forEach(function(x){x.disabled=true;});document.getElementById("lf").textContent=b.textContent===target?"✓ ¡Has reconocido la palabra!":"La palabra clave era: "+target;document.getElementById("ln").hidden=false;};});}document.getElementById("showt").onclick=function(){document.getElementById("lt").hidden=!document.getElementById("lt").hidden;};document.getElementById("ln").onclick=function(){li++;if(li>=ls.length){document.getElementById("lq").textContent="¡Has completado Listening!";document.getElementById("lo").innerHTML="";document.getElementById("ln").hidden=true;document.getElementById("lp").disabled=true;}else lr();};lr();var st=document.createElement("style");st.textContent=".skill-card{margin:16px 0;padding:18px;border:1px solid #dce6f7;border-radius:16px;background:linear-gradient(145deg,#f4f8ff,#fff)}.skill-example{font-size:19px;font-weight:850;color:#284a88}.skill-passage{padding:20px;border:1px solid #dce6f7;border-radius:16px;background:#f1f6ff;color:#294777;font-size:18px;line-height:1.9;margin:16px 0}";document.head.appendChild(st);})();
